const item = $input.item;
item.binary.data.fileName = 'voice.ogg';
item.binary.data.mimeType = 'audio/ogg';
return item;

const items = $input.all();
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
const now = Date.now();
for (const k of Object.keys(sd.seen)) {
  if (now - sd.seen[k] > 24 * 3600 * 1000) delete sd.seen[k];
}
const out = [];
for (const it of items) {
  const id = it.json.messages?.[0]?.id;
  if (!id) { out.push(it); continue; }
  if (sd.seen[id]) continue;
  sd.seen[id] = now;
  out.push(it);
}
return out;

let t = String($json.output ?? '').trim();
t = t.replace(/\*\*(.+?)\*\*/gs, '*$1*').replace(/__(.+?)__/gs, '_$1_').replace(/^#{1,6}\s*/gm, '').replace(/^\s*[\u2022\u25CF\u25AA]\s*/gm, '- ').replace(/\x60{1,3}/g, '').replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1 ($2)').replace(/\n{3,}/g, '\n\n').trim();
if (!t) t = 'Sorry, I could not prepare a reply. Please try again or email support@oakmereliving.example.';
if (t.length > 1500) t = t.slice(0, 1500).trim() + '...';
return { json: { output: t } };

